<template>
 <div class="account">
  <button class="back" type="button" @click="codeEditing ? codeEditing='' : selected ? selected=null : $emit('home')">‹ {{ codeEditing ? 'Back to Identity documents' : selected ? 'Back to My Profile' : 'Back to app' }}</button>
  <ShareCodeUpdate v-if="codeEditing" :key="codeEditing" :kind="codeEditing" :saving="codeSaving" :feedback="codeFeedback" @submit="value => { codeValue=value; saveCode() }" @cancel="codeEditing=''" />
  <template v-else-if="!selected">
   <div class="hero"><img v-if="values.id_photo" :src="values.id_photo" alt="Your profile photo"><span v-else class="avatar">{{ initials }}</span><div><span class="eyebrow">MY ACCOUNT</span><h2>{{ fullName || 'Your profile' }}</h2><p>Your details, all in one place.</p></div></div>
   <div class="cards"><button v-for="group in groups" :key="group.title" type="button" class="card" :class="{'needs-action':needsAction(group)}" @click="selected=group"><span class="icon" aria-hidden="true">{{ group.icon }}</span><span><strong>{{ group.title }}</strong><small>{{ group.description }}</small><span v-if="needsAction(group)" class="action-label">Action required</span></span><span class="chevron" aria-hidden="true">›</span></button></div>
   <p class="footnote">Your saved onboarding details. Need to make a correction? Contact the team through Chat.</p>
  </template>
  <section v-else class="detail"><span class="eyebrow">MY PROFILE</span><div class="detail-heading"><h2 tabindex="-1" ref="heading">{{ selected.title }}</h2><button v-if="!editing && canUpdate" type="button" class="update-button" @click="beginUpdate">Update</button></div><p v-if="selected.title !== 'Driving Licence'">{{ selected.description }}</p><ProfileCompliance v-if="selected.title==='Compliance'" :values="values" @open="openComplianceTarget" /><p v-if="previewPassportUpdate && selected.title==='Identity documents'" class="footnote">TEST PREVIEW — Update is shown for layout testing. Your passport details are unchanged.</p><ProfileDocumentCapture v-if="editing && selected.title==='Identity documents'" kind="passport" label="Replacement passport" @captured="replacementReady=false" @saved="replacementSaved" /><p v-if="editing && selected.title==='Identity documents' && replacementReady" role="status">Check the details read from your new passport, correct anything missing, then submit.</p><dl v-if="selected.title!=='Compliance' && !(editing && selected.title==='Identity documents' && !replacementReady)" :class="{'two-columns': ['Driving Licence','Identity documents','Address','Contact information'].includes(selected.title), 'identity-grid': selected.title === 'Identity documents'}"><div v-for="field in selected.fields" :key="field[0]" :data-field="field[0]" class="row"><dt>{{ field[1] }}</dt><dd v-if="isFile(field[0])"><button v-if="safeFile(values[field[0]])" type="button" class="document-link" @click="openDocument(field,$event)">View</button><span v-else>Not provided</span></dd><dd v-else-if="editing && editable(field[0])"><label class="sr-only" :for="'update-'+field[0]">{{ field[1] }}</label><input :id="'update-'+field[0]" v-model="changes[field[0]]" :type="inputType(field[0])" :inputmode="field[0]==='mobile'?'tel':undefined" /></dd><dd v-else>{{ display(field[0]) }}</dd></div></dl><div v-if="selected.title==='Identity documents' && !editing && requiresImmigration(values)" class="identity-support"><p v-if="codeFeedback" role="status">{{ codeFeedback }}</p>
<section><div class="detail-heading"><h3>Right to Work</h3><button type="button" class="update-button" :disabled="codeSaving" @click="editCode('portal_rtw_share_code')">Update</button></div><form v-if="codeEditing==='portal_rtw_share_code'" class="code-editor" @submit.prevent="saveCode"><label for="share-code-update">New share code</label><input id="share-code-update" v-model="codeValue" required maxlength="140" autocomplete="off" :disabled="codeSaving" /><div class="edit-actions"><button type="submit" :disabled="codeSaving">{{ codeSaving ? 'Saving…' : 'Save share code' }}</button><button type="button" :disabled="codeSaving" @click="codeEditing=''">Cancel</button></div></form><dl class="two-columns"><div v-for="field in rtwFields.filter(field => hasValue(field[0]))" :key="field[0]" class="row"><dt>{{ field[1] }}</dt><dd v-if="field[2]"><button v-if="safeFile(values[field[0]])" type="button" class="document-link" @click="openDocument(field,$event)">View</button><span v-else>Not provided</span></dd><dd v-else>{{ display(field[0]) }}</dd></div></dl></section>
<section><div class="detail-heading"><h3>Immigration</h3><button type="button" class="update-button" :disabled="codeSaving" @click="editCode('portal_immigration_share_code')">Update</button></div><form v-if="codeEditing==='portal_immigration_share_code'" class="code-editor" @submit.prevent="saveCode"><label for="share-code-update">New share code</label><input id="share-code-update" v-model="codeValue" required maxlength="140" autocomplete="off" :disabled="codeSaving" /><div class="edit-actions"><button type="submit" :disabled="codeSaving">{{ codeSaving ? 'Saving…' : 'Save share code' }}</button><button type="button" :disabled="codeSaving" @click="codeEditing=''">Cancel</button></div></form><dl class="two-columns"><div v-for="field in immigrationFields.filter(field => hasValue(field[0]))" :key="field[0]" class="row"><dt>{{ field[1] }}</dt><dd v-if="field[2]"><button v-if="safeFile(values[field[0]])" type="button" class="document-link" @click="openDocument(field,$event)">View</button><span v-else>Not provided</span></dd><dd v-else>{{ display(field[0]) }}</dd></div></dl></section>
</div><template v-if="editing"><p>Saved documents remain on file. Contact the team if you need to replace a document or change your login email.</p><p v-if="updateError" role="alert" class="update-error">{{ updateError }}</p><div class="edit-actions"><button v-if="selected.title!=='Identity documents' || replacementReady" type="button" :disabled="saving" @click="saveUpdate">{{ saving ? 'Saving…' : selected.title==='Identity documents' ? 'Submit passport' : 'Save changes' }}</button><button type="button" :disabled="saving" @click="editing=false">Cancel</button></div></template><p v-if="savedMessage" role="status">{{ savedMessage }}</p></section>
  <Teleport to="body"><div v-if="documentPreview" class="preview-backdrop" @click.self="closeDocument" @keydown.esc="closeDocument" @keydown.tab="trapPreview">
   <section class="document-sheet" role="dialog" aria-modal="true" aria-labelledby="document-preview-title">
    <header><h2 id="document-preview-title">{{ documentPreview.title }}</h2><button ref="closeButton" type="button" @click="closeDocument">Close</button></header>
    <div class="preview-content"><img v-if="!documentPreview.pdf" :src="documentPreview.url" :alt="documentPreview.title" @error="previewFailed=true"><iframe v-else :src="documentPreview.url" :title="documentPreview.title" /><p v-if="previewFailed" role="alert">This document could not be displayed. Close the preview and try again.</p></div>
   </section>
  </div></Teleport>
 </div>
</template>
<script setup>
import {computed,ref,watch,nextTick} from 'vue'
import ShareCodeUpdate from './ShareCodeUpdate.vue'
import ProfileCompliance from './ProfileCompliance.vue'
import ProfileDocumentCapture from './ProfileDocumentCapture.vue'
import {licenceType,requiresImmigration} from '@/utils/profileProgress'
import {session} from '@/data/session'
function logoutAccount(){sessionStorage.removeItem('sdt-test-contact-name');if(['127.0.0.1','localhost'].includes(location.hostname)){location.href='https://erp.onemotion.uk/login';return}session.logout.submit()}
import {saveProfile} from '@/data/onboarding'
const props=defineProps({values:{type:Object,required:true},errors:{type:Object,default:()=>({})}})
const auditGroups={'Driving Licence':['dlm','dvla','dva'],'Identity documents':['pdm','bcm','rtw','imi'],'Address':['adm'],'Tax details':['nim'],'Background screening':['dbs']}
function needsAction(group){const action=v=>['action required','action_required','rejected','expired','failed'].includes(String(v||'').trim().toLowerCase());if(group.title==='Compliance')return action(props.values.audit_status)||Object.keys(props.values).some(k=>k.startsWith('audit_status_')&&action(props.values[k]));return (auditGroups[group.title]||[]).some(k=>action(props.values['audit_status_'+k]))||group.fields.some(([key])=>!!props.errors[key])}

const emit=defineEmits(['home','saved','agreements'])
const editing=ref(false),changes=ref({}),saving=ref(false),updateError=ref(''),savedMessage=ref('')
const codeEditing=ref(''),codeValue=ref(''),codeSaving=ref(false),codeFeedback=ref('')
const hasValue=key=>{const v=key==='primary_rtw_share_code'?props.values[key]||props.values.portal_rtw_share_code:key==='primary_immigration_share_code'?props.values[key]||props.values.portal_immigration_share_code:props.values[key];return v!==null&&v!==undefined&&String(v).trim()!==''}
function editCode(key){codeEditing.value=key;codeValue.value='';codeFeedback.value=''}
async function saveCode(){const key=codeEditing.value,value=codeValue.value.replace(/\s+/g,'').toUpperCase();const prefix=key==='portal_rtw_share_code'?'W':'S';if(!new RegExp('^'+prefix+'[A-Z0-9]{8}$').test(value)){codeFeedback.value='Enter nine letters and numbers beginning with '+prefix+'.';return;}codeSaving.value=true;codeFeedback.value='';try{const state=await saveProfile({[key]:value},false,[]);emit('saved',state);codeEditing.value='';codeFeedback.value='Share code saved for review.'}catch(error){codeFeedback.value=error?.messages?.[0]||error?.message||'Could not save the share code. Please try again.'}finally{codeSaving.value=false}}
const previewPassportUpdate=['127.0.0.1','localhost'].includes(location.hostname)&&new URLSearchParams(location.search).get('preview_passport_update')==='1'
const replacementReady=ref(false)
const canUpdate=computed(()=>{if(['Personal details','Compliance'].includes(selected.value?.title))return false;if(selected.value?.title!=='Identity documents')return true;if(previewPassportUpdate)return true;const v=props.values;const now=new Date();const today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');return !!v.passport_expiry_date&&v.passport_expiry_date<today&&!!v.birth_nationality&&!['british','british citizen'].includes(String(v.birth_nationality).toLowerCase())&&(!v.portal_identity_type||v.portal_identity_type==='Passport')})
function replacementSaved(result){emit('saved',result.profile);changes.value=Object.fromEntries(['passport_number','passport_issuing_country','passport_issue_date','passport_expiry_date'].map(k=>[k,result.suggestions?.[k]||'']));replacementReady.value=true}
const editable=key=>(selected.value?.title!=='Identity documents'||(replacementReady.value&&key.startsWith('passport_')))&&!files.has(key)&&!['email','portal_identity_type','portal_no_passport','portal_no_driving_licence'].includes(key)
const inputType=key=>key==='mobile'?'tel':/date|expiry|^dob$|address_since/.test(key)?'date':'text'
function beginUpdate(){replacementReady.value=false;changes.value=Object.fromEntries(selected.value.fields.filter(([key])=>editable(key)).map(([key])=>[key,props.values[key]??'']));editing.value=true;updateError.value='';savedMessage.value=''}
async function saveUpdate(){saving.value=true;updateError.value='';try{const changed=Object.fromEntries(Object.entries(changes.value).filter(([key,value])=>String(value)!==String(props.values[key]??'')));const state=await saveProfile(changed,false,Object.keys(changed));emit('saved',state);editing.value=false;savedMessage.value='Changes saved.'}catch(error){updateError.value=error?.messages?.[0]||error?.message||'Could not save changes. Please try again.'}finally{saving.value=false}}
const selected=ref(null),heading=ref(null)
const documentPreview=ref(null),closeButton=ref(null),previewFailed=ref(false)
let previewTrigger
async function openDocument(field,event){previewTrigger=event.currentTarget;previewFailed.value=false;const url=props.values[field[0]];documentPreview.value={url,title:field[1],pdf:/\.pdf(?:[?#]|$)/i.test(url)};await nextTick();closeButton.value?.focus()}
async function closeDocument(){documentPreview.value=null;await nextTick();previewTrigger?.focus()}
function trapPreview(event){if(event.target===closeButton.value){event.preventDefault();closeButton.value?.focus()}}

watch(selected,async value=>{editing.value=false;savedMessage.value='';if(value){await nextTick();heading.value?.focus()}})
const fullName=computed(()=>['first_name','middle_name','last_name'].map(k=>props.values[k]).filter(Boolean).join(' '))
const initials=computed(()=>[props.values.first_name,props.values.last_name].filter(Boolean).map(s=>s[0]).join(''))
const immigrationFields=[['primary_immigration_share_code','Share code'],['primary_imi_indefinite','Indefinite'],['primary_immigration_status','Share code status'],['primary_imi_outcome_status','Outcome status'],['primary_immigration_sc_ed','Share code expiry date'],['primary_immigration_outcome_expiry','Outcome expiry'],['primary_immigration_share_code_doc','Immigration share code file',true],['primary_immigration_dd_file','Immigration outcome document',true]]
const rtwFields=[['primary_rtw_share_code','Share code'],['primary_rtw_indefinite','Indefinite'],['primary_rtw_status','Share code status'],['primary_rtw_outcome__status','Outcome status'],['primary_rtw_sc_ed','Share code expiry date'],['primary_rtw_outcome_expiry','Outcome expiry'],['primary_rtw_share_code_file','Right to Work share code file',true],['primary_rtw_dd_file','Right to Work outcome document',true]]
const files=new Set(['passp_file','bc_file','tab_dl_photocard_front','tab_dl_photocard_rear','proof_of_address_doc','portal_dbs_certificate_file'])
const isFile=k=>files.has(k)
const safeFile=v=>typeof v==='string'&&(/^\/(?!\/)/.test(v)||/^https?:\/\//.test(v)||/^data:image\//.test(v))
const display=k=>{if(k==='primary_immigration_share_code')return props.values[k]||props.values.portal_immigration_share_code||'Not provided';if(k==='primary_rtw_share_code')return props.values[k]||props.values.portal_rtw_share_code||'Not provided';const v=k==='dl_type' ? props.values[k]||licenceType(props.values.dl_issuing_country) : props.values[k];if(v===undefined||v===null||v==='')return 'Not provided';if(k==='portal_no_driving_licence'||k==='portal_no_passport')return ['1','true','yes'].includes(String(v).toLowerCase())?'Yes':'No';return typeof v==='object'?'On file':String(v)}
function openComplianceTarget(target){if(target==='agreements'){emit('agreements');return}if(target==='app'){emit('home');return}selected.value=groups.value.find(g=>g.title===target)||null}
const groups=computed(()=>[
 {title:'Compliance',icon:'✓',description:'Audit results and anything needing attention',fields:[]},
 {title:'Personal details',icon:'◉',description:'Name, date of birth and nationality',fields:[['first_name','First name'],['middle_name','Middle name'],['last_name','Last name'],['dob','Date of birth'],['birthpassport_gender','Birth gender'],['birth_country','Birth country'],['birth_city','Birth town / city'],['birth_nationality','Nationality'],['preferred_language','Preferred language']]},
 {title:'Identity documents',icon:'▤',description:'Passport, travel document or birth certificate',fields:[['portal_identity_type','Document type'],['passport_number','Passport / travel document number'],['passport_issuing_country','Issuing country'],['passport_issue_date','Issue date'],['passport_expiry_date','Expiry date'],['passp_file','Document photo'],['bc_file','Birth certificate']].filter(([key])=>key!=='bc_file'||!!props.values.bc_file)},
 {title:'Driving Licence',icon:'▣',description:'Licence details and saved photos',fields:[['portal_no_driving_licence','No driving licence declared'],['dl_number','Licence number'],['dl_type','Licence Type'],['dl_issue_date','Issue date'],['dl_photocard_expiry','Photocard expiry'],['dl_expiry_date','Licence expiry'],['dl_issuing_country','Issuing country'],['tab_dl_photocard_front','Front photo'],['tab_dl_photocard_rear','Back photo']].filter(([key])=>!(key==='portal_no_driving_licence' && [props.values.dl_number,props.values.tab_dl_photocard_front,props.values.tab_dl_photocard_rear].some(v=>String(v??'').trim()))).filter(([key])=>files.has(key)?safeFile(props.values[key]):(key==='dl_type'&&!!props.values.dl_issuing_country)||(props.values[key]!==undefined&&props.values[key]!==null&&String(props.values[key]).trim()!==''))},
 {title:'Address',icon:'⌂',description:'Home address and proof of address',fields:[['street_address','Street address'],['address_since','Move-in date'],['city','Town / city'],['state_region','County / region'],['postal_code','Postcode'],['country','Country'],['proof_of_address_doc','Proof of address']]},
 {title:'Contact information',icon:'@',description:'Email address and mobile number',fields:[['email','Email'],['mobile','Mobile']]},
 {title:'Tax details',icon:'▤',description:'National Insurance, UTR and VAT numbers — no file uploads needed. Enter a VAT number if registered.',fields:[['nino_number','National Insurance number'],['utr_number','UTR number'],['vat_number','VAT number']]},
 {title:'Background screening',icon:'✓',description:'Your submitted screening information',fields:[['portal_has_recent_dbs','Recent DBS check'],['portal_has_dbs_share_code','Has share code'],['portal_dbs_share_code','DBS share code'],['portal_dbs_reference','Reference number'],['portal_dbs_certificate_file','DBS certificate'],['mothers_first_name','Mother’s first name'],['mothers_maiden_name','Mother’s maiden name']].filter(([key])=>props.values[key]!==undefined&&props.values[key]!==null&&props.values[key]!=='')},
 ...(['portal_rtw_share_code','portal_immigration_share_code'].some(k=>props.values[k])?[{title:'Right to work & immigration',icon:'◇',description:'Your saved share codes',fields:[['portal_rtw_share_code','Right to Work share code'],['portal_immigration_share_code','Immigration share code']]}]:[])
])
</script>
<style scoped>
.card.needs-action{border:1px solid #b42318;background:#fff5f4}.card.needs-action .icon{background:#fee4e2;color:#b42318}.action-label{display:inline-block;margin-top:8px;padding:3px 8px;border-radius:6px;color:#b42318;background:#fee4e2;font-size:12px;font-weight:600}

.identity-support .update-button{background:transparent;border:0;color:#a61d1d;font-size:.75rem;font-weight:500;padding:.25rem .35rem;min-height:32px;border-radius:4px}.identity-support .update-button:hover{text-decoration:underline}

.code-editor{padding:1rem 0}.code-editor label{display:block;font-size:.8rem;margin-bottom:.5rem}.code-editor input{box-sizing:border-box;width:100%;padding:.7rem;border:1px solid #aab5c3;border-radius:8px;font:inherit}

.identity-support{display:grid;gap:1.25rem;margin-top:1.5rem}.identity-support h3{font-size:1.1rem;font-weight:600;margin:0}.identity-support dl{margin-top:.65rem}

.identity-grid .row[data-field="portal_identity_type"]{grid-column:1;grid-row:1}
.identity-grid .row[data-field="passport_number"]{grid-column:2;grid-row:2}
.identity-grid .row[data-field="passport_issuing_country"]{grid-column:1;grid-row:2}
.identity-grid .row[data-field="passport_issue_date"]{grid-column:2;grid-row:3}
.identity-grid .row[data-field="passport_expiry_date"]{grid-column:1;grid-row:3}
.identity-grid .row[data-field="passp_file"]{grid-column:1;grid-row:4}
.identity-grid .row[data-field="bc_file"]{grid-column:2;grid-row:4}

.detail dl.two-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.two-columns .row{min-width:0;border-bottom:1px solid #eef0f4}.two-columns .row:nth-child(odd){border-right:1px solid #eef0f4}.two-columns dd{overflow-wrap:anywhere}

.detail-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem}.update-button,.edit-actions button{border:0;background:#a61d1d;color:white;border-radius:8px;padding:.65rem 1rem;min-height:44px;cursor:pointer}.edit-actions{display:flex;gap:.75rem;margin-top:1rem}.edit-actions button:last-child{background:#eef2f6;color:#17202b}.row input{width:100%;box-sizing:border-box;border:1px solid #aab5c3;border-radius:7px;padding:.65rem;font:inherit}.update-error{color:#b91c1c}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}

.document-link{display:inline-flex;align-items:center;justify-content:center;background:#f2f5f8;border:1px solid #dce3ea;color:#30475e;padding:.35rem .9rem;min-height:36px;border-radius:7px;cursor:pointer;font-size:.8rem;font-weight:600;text-decoration:none}.document-link:hover{background:#e8eef4}.document-link:focus-visible{outline:2px solid #2461a6;outline-offset:2px}
.preview-backdrop{position:fixed;inset:0;z-index:10000;background:#10182788;display:flex;align-items:flex-end;justify-content:center;padding-top:2rem}
.document-sheet{width:min(100%,760px);height:88dvh;background:#fff;border-radius:20px 20px 0 0;box-shadow:0 -8px 40px #0003;display:flex;flex-direction:column;padding-bottom:env(safe-area-inset-bottom)}
.document-sheet header{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem 1.25rem;border-bottom:1px solid #e4e8ee}.document-sheet h2{font-size:1rem;margin:0}.document-sheet header button{background:#eef2f6;border:0;border-radius:8px;min-height:44px;padding:0 1rem;color:#17202b;cursor:pointer}.preview-content{flex:1;min-height:0;overflow:auto;background:#f5f7fa;padding:1rem}.preview-content img{display:block;max-width:100%;max-height:100%;object-fit:contain;margin:auto}.preview-content iframe{width:100%;height:100%;border:0}

.account{padding:0 0 2rem;color:#17202b}.back{background:transparent;color:#a61d1d;padding:.5rem 0;min-height:44px;font-size:.9rem;border:0;cursor:pointer}.hero{display:flex;align-items:center;gap:1rem;padding:1.6rem 0 2rem}.hero img,.avatar{width:72px;height:72px;border-radius:50%;object-fit:cover;background:#e8f1fc;flex-shrink:0}.avatar{display:grid;place-items:center;color:#2461a6;font-size:1.5rem;font-weight:600}.eyebrow{font-size:.65rem;letter-spacing:.14em;color:#738090;font-weight:600}h2{font-size:1.45rem;line-height:1.25;font-weight:650;margin:.35rem 0}p{font-size:.85rem;color:#697586;margin:.4rem 0}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}.card{display:flex;align-items:center;gap:.75rem;text-align:left;padding:1.1rem;background:white;border:1px solid #e4e8ee;border-radius:14px;box-shadow:0 3px 12px #18233305;min-height:100px;color:#17202b;cursor:pointer}.card:hover{border-color:#a9bbc8;background:#fafcfe}.icon{background:#eef4fa;border-radius:10px;width:36px;height:36px;display:grid;place-items:center;font-size:1.2rem;color:#355e85;flex-shrink:0}.card strong{display:block;font-size:.9rem;font-weight:600}.card small{display:block;font-size:.75rem;line-height:1.4;color:#697586;margin-top:.35rem}.chevron{margin-left:auto;color:#8c98a6;font-size:1.4rem}.footnote{margin-top:1.25rem;font-size:.75rem;line-height:1.6}.detail{padding:1rem 0}.detail dl{border:1px solid #e4e8ee;border-radius:14px;margin-top:1.3rem;overflow:hidden}.row{padding:.9rem 1rem;border-bottom:1px solid #eef0f4}.row:last-child{border:0}dt{font-size:.75rem;color:#697586;margin-bottom:.3rem}dd{font-size:.95rem;overflow-wrap:anywhere;margin:0}a{color:#a61d1d}button:focus-visible,a:focus-visible{outline:2px solid #2461a6;outline-offset:3px}@media(max-width:480px){.cards{grid-template-columns:1fr}.card{min-height:82px}.hero h2{font-size:1.25rem}}
</style>
